function determineBump(commitMessages) {
  let best = null;
  for (const msg of commitMessages) {
    const { level } = classifyCommit(msg);
    if (level && (!best || LEVEL_RANK[level] > LEVEL_RANK[best])) best = level;
    if (best === 'major') break; // can't rank higher
  }
  return best;
}

